export function StatusBadge({ status }: { status: string }) {
  const cls =
    status === 'Completed'
      ? 'badge-green'
      : status === 'Confirmed'
        ? 'badge-blue'
        : status === 'Cancelled'
          ? 'badge-red'
          : 'badge-orange';
  return <span className={`badge ${cls}`}>{t(`order.status.${status}`) === `order.status.${status}` ? status : t(`order.status.${status}`)}</span>;
}
